UPDATE tb_contract_mst
SET    attach_file_id = #{attachFileId}
WHERE  contract_id    = #{contractId}

UPDATE tb_contract_mst
SET    manager_id          = #{managerId}
      ,client_id           = #{clientId}
      ,client_no           = #{clientNo}
      ,vat_type            = #{vatType}
      ,etc                 = #{etc}
      ,upd_id              = #{userId}
      ,upd_dt              = GETDATE()
WHERE contract_id = #{contractId}

